CREATE FUNCTION fun(query_from_time date) RETURNS TABLE(foo double precision, bar double precision)
    LANGUAGE plpgsql
    AS $$
      BEGIN
       RETURN QUERY
      WITH bla AS (
        SELECT * from foo)
      Select * from bla;
      END;
      $$;

CREATE PROCEDURE remove_emp (employee_id NUMBER) AS
   tot_emps NUMBER;
   BEGIN
      DELETE FROM employees
      WHERE employees.employee_id = remove_emp.employee_id;
   tot_emps := tot_emps - 1;
   END;

